use crate::catalog::Template;

pub fn guide(template: &Template) -> String {
    let tree = match template.integration_adapter.as_deref() {
        Some("node-nest") => {
            "src/\n  app.module.ts                   # composition root: importa módulos\n  config/env.ts                   # leitura/validação das variáveis\n  infrastructure/\n    infrastructure.module.ts      # startup/shutdown dos recursos\n    database/client.ts            # pool/conexão, ping e encerramento\n    database/schema.ts            # preparação explícita do exemplo\n    cache/client.ts               # cliente Redis, sem regras de negócio\n  modules/example/\n    example.module.ts             # registra controller, service e repository\n    example.controller.ts         # HTTP e validação de entrada\n    example.service.ts            # caso de uso e cache-aside\n    repositories/example.repository.ts # consultas SQL/driver Mongo\n"
        }
        Some("node-express") => {
            "src/\n  config/                         # ambiente e validação\n  infrastructure/database/        # conexão, disponibilidade e preparação\n  http/                           # rotas e middlewares globais\n  modules/example/\n    controllers/                  # HTTP/validação\n    services/                     # regras e coordenação do cache\n    repositories/                 # consultas SQL/driver Mongo\n"
        }
        Some("go-http") => {
            "cmd/api/main.go                   # composição, sinais e shutdown\ninternal/\n  config/config.go                 # ambiente validado\n  httpapi/router.go                # rotas, CORS, health/readiness\n  modules/example/\n    controller.go                  # protocolo HTTP\n    service.go                     # caso de uso\n    repositories/                  # somente quando banco selecionado\n"
        }
        Some("python-fastapi") => {
            "app/\n  main.py                         # fábrica FastAPI, CORS e routers\n  config.py                       # ambiente e segredos por arquivo\n  infrastructure/\n    lifecycle.py                  # lifespan: abre/fecha recursos\n    database.py                   # conexão e readiness\n    schema.py                     # preparação explícita do exemplo\n    cache.py                      # cliente Redis\n  modules/example/\n    router.py                     # HTTP e Depends\n    schemas.py                    # contratos Pydantic de entrada/saída\n    service.py                    # caso de uso e dependências por request\n    repository.py                 # consultas parametrizadas/driver Mongo\n"
        }
        _ => {
            "src/\n  lib.rs                          # composição das rotas\n  infrastructure/                 # config, conexão, cache e métricas\n  modules/example/\n    mod.rs                        # declara as camadas do módulo\n    controller.rs                 # protocolo HTTP e validação\n    service.rs                    # caso de uso e coordenação do cache\n    repositories/mod.rs           # consultas SQL/driver Mongo\n"
        }
    };
    format!(
        "# Arquitetura da API\n\nOrganização por funcionalidade com camadas explícitas. Arquivos de integrações só existem quando selecionados: este mapa mostra também as posições dos módulos opcionais.\n\n```text\n{tree}```\n\nO fluxo é HTTP → controller/router → service → repository → cliente do banco. A configuração somente lê/valida valores; o cliente do banco somente cria, verifica e fecha conexões. Consultas de domínio ficam no repository. A preparação de schema fica em um comando explícito; não é executada a cada startup.\n\nServices não recebem request/response HTTP nem montam SQL. Controllers não acessam banco. O repository não conhece Redis nem escolhe códigos HTTP. O service invalida o cache após a escrita ter sucesso. Cache-aside tem consistência eventual (TTL de 30s), inclusive em leituras concorrentes à invalidação; use uma política mais forte se seu caso exigir.\n\nNest usa um Module por funcionalidade, providers registrados e injeção do repository no service. As conexões Node são compartilhadas por processo e geridas pelo lifecycle; não crie duas aplicações concorrentes com configurações diferentes no mesmo processo. Python mantém recursos no app.state e injeta services/repositories via Depends, sem conexão global. Rust mantém um pool por processo e funções de camada distintas.\n\nPara adicionar uma funcionalidade, crie um novo módulo ao lado de example com seus contratos HTTP, regras e repository (quando necessário), registre-o na composição e escreva testes de comportamento. Evite um repository genérico que esconda consultas específicas. Esta base não impõe DDD/Clean Architecture nem um ORM.\n\nAntes de fazer commit, execute os checks do README. Lint não substitui testes de integração com banco real. /health mede liveness; /ready verifica o banco obrigatório. Nunca exponha credenciais nos erros HTTP.\n"
    )
}
